{
  "name": "Nebulizer Scheduling System (KD 2026)",
  "description": "A specialized tool for hospitals to schedule nebulization sessions according to strict medical regulations, staffing limits, and equipment availability."
}

export interface PatientInput {
  name: string;
  firstDoseTime: string; // HH:mm
  frequency: number; // 2 or 3
}

export interface Nurse {
  id: string;
  name: string;
  isSpecialist: boolean; // Nurse C
}

export interface Machine {
  id: string;
  isStandard: boolean; // 032, 121 are always available, 368 is office only
}

export interface ScheduleEntry {
  stt: number;
  patientName: string;
  doseNumber: number;
  startTime: string; // HH:mm
  endTime: string; // HH:mm
  nurseName: string;
  machineId: string;
  isOffHours: boolean;
  notes: string;
  rawMinutes: number; // Used for sorting if needed
}

export interface SchedulingConfig {
  nurse1: string;
  nurse2: string;
  nurseC: string;
}

import { 
  PatientInput, 
  ScheduleEntry, 
  SchedulingConfig 
} from './types';
import { 
  OFFICE_START, 
  OFFICE_END, 
  EXECUTION_OFFSET, 
  DURATION, 
  MAX_DELAY, 
  DOSE3_EARLY_LIMIT,
  MACHINES
} from './constants';

const timeToMinutes = (time: string): number => {
  const [h, m] = time.split(':').map(Number);
  return h * 60 + m;
};

const minutesToTime = (minutes: number): string => {
  const h = Math.floor((minutes % 1440) / 60);
  const m = Math.floor(minutes % 60);
  return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
};

const isOfficeHours = (minutes: number): boolean => {
  const normalized = minutes % 1440;
  return normalized >= OFFICE_START && normalized <= OFFICE_END;
};

export const generateSchedule = (
  patients: PatientInput[],
  config: SchedulingConfig
): ScheduleEntry[] => {
  const allSlots: { 
    patientName: string; 
    doseNumber: number; 
    targetMinutes: number; 
    isDose3: boolean;
    frequency: number;
  }[] = [];

  // 1. Generate all theoretical slots
  patients.forEach(p => {
    const firstMinutes = timeToMinutes(p.firstDoseTime);
    const interval = p.frequency === 2 ? 12 * 60 : 8 * 60;

    for (let i = 0; i < p.frequency; i++) {
      allSlots.push({
        patientName: p.name,
        doseNumber: i + 1,
        targetMinutes: firstMinutes + (i * interval),
        isDose3: i === 2 && p.frequency === 3,
        frequency: p.frequency
      });
    }
  });

  // Sort slots by target time initially
  allSlots.sort((a, b) => a.targetMinutes - b.targetMinutes);

  const finalSchedule: ScheduleEntry[] = [];

  // Track resource usage
  // Structure: { [minutes]: { nurses: string[], machines: string[] } }
  const usage: Record<number, { nurses: string[]; machines: string[] }> = {};

  const isResourceAvailable = (
    start: number, 
    nurse: string, 
    machine: string
  ): boolean => {
    for (let t = start; t < start + DURATION; t++) {
      const timeUsage = usage[t % 1440];
      if (timeUsage) {
        if (timeUsage.nurses.includes(nurse) || timeUsage.machines.includes(machine)) {
          return false;
        }
      }
    }
    return true;
  };

  const bookResources = (
    start: number, 
    nurse: string, 
    machine: string
  ) => {
    for (let t = start; t < start + DURATION; t++) {
      const min = t % 1440;
      if (!usage[min]) usage[min] = { nurses: [], machines: [] };
      usage[min].nurses.push(nurse);
      usage[min].machines.push(machine);
    }
  };

  // 2. Process each slot and resolve conflicts
  allSlots.forEach(slot => {
    let bestStart = slot.targetMinutes + EXECUTION_OFFSET;
    let assignedNurse = "";
    let assignedMachine = "";
    let found = false;

    // Time window for searching:
    // Regular: [target, target + 30]
    // Dose 3: [target - 60, target + 30]
    const searchStart = slot.isDose3 ? bestStart - DOSE3_EARLY_LIMIT : bestStart;
    const searchEnd = bestStart + MAX_DELAY;

    for (let t = searchStart; t <= searchEnd; t++) {
      const office = isOfficeHours(t);
      const availableNurses = office 
        ? [config.nurse1, config.nurse2, config.nurseC] 
        : [config.nurse1, config.nurse2];
      const availableMachines = office
        ? [...MACHINES.ALWAYS, ...MACHINES.OFFICE]
        : [...MACHINES.ALWAYS];

      // Try every combination of nurse and machine
      for (const n of availableNurses) {
        for (const m of availableMachines) {
          if (isResourceAvailable(t, n, m)) {
            bestStart = t;
            assignedNurse = n;
            assignedMachine = m;
            found = true;
            break;
          }
        }
        if (found) break;
      }
      if (found) break;
    }

    if (found) {
      bookResources(bestStart, assignedNurse, assignedMachine);
      finalSchedule.push({
        stt: 0, // Placeholder
        patientName: slot.patientName,
        doseNumber: slot.doseNumber,
        startTime: minutesToTime(bestStart),
        endTime: minutesToTime(bestStart + DURATION),
        nurseName: assignedNurse,
        machineId: assignedMachine,
        isOffHours: !isOfficeHours(bestStart),
        notes: !isOfficeHours(bestStart) ? "Ngoài giờ" : "",
        rawMinutes: bestStart
      });
    } else {
      // Emergency fallback if absolutely no slot found (should not happen with given constraints)
      finalSchedule.push({
        stt: 0,
        patientName: slot.patientName,
        doseNumber: slot.doseNumber,
        startTime: minutesToTime(bestStart),
        endTime: minutesToTime(bestStart + DURATION),
        nurseName: "CHƯA PHÂN CÔNG",
        machineId: "HẾT MÁY",
        isOffHours: !isOfficeHours(bestStart),
        notes: "Xung đột nghiêm trọng",
        rawMinutes: bestStart
      });
    }
  });

  // 3. Final formatting: Sort by Patient Name (Unicode)
  return finalSchedule
    .sort((a, b) => a.patientName.localeCompare(b.patientName, 'vi'))
    .map((entry, idx) => ({ ...entry, stt: idx + 1 }));
};

import React, { useState, useMemo } from 'react';
import { createRoot } from 'react-dom/client';
import { generateSchedule } from './schedulerLogic';
import { PatientInput, SchedulingConfig, ScheduleEntry } from './types';
import { DEFAULT_PATIENTS } from './constants';

const App: React.FC = () => {
  const [patientText, setPatientText] = useState<string>(DEFAULT_PATIENTS);
  const [nurse1, setNurse1] = useState<string>('Nguyễn Văn Trực A');
  const [nurse2, setNurse2] = useState<string>('Lê Thị Trực B');
  const [nurseC, setNurseC] = useState<string>('Phạm Văn C (Hành chính)');
  const [schedule, setSchedule] = useState<ScheduleEntry[]>([]);
  const [error, setError] = useState<string | null>(null);

  const parsePatients = (text: string): PatientInput[] => {
    return text
      .split('\n')
      .filter((line) => line.trim())
      .map((line) => {
        const parts = line.split('-').map((s) => s.trim());
        if (parts.length < 3) throw new Error(`Dòng không đúng định dạng: ${line}`);
        const [name, time, freq] = parts;
        if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) throw new Error(`Giờ không hợp lệ: ${time}`);
        const f = parseInt(freq, 10);
        if (isNaN(f) || (f !== 2 && f !== 3)) throw new Error(`Số lần phun phải là 2 hoặc 3: ${freq}`);
        return { name, firstDoseTime: time, frequency: f };
      });
  };

  const handleGenerate = () => {
    try {
      setError(null);
      const patients = parsePatients(patientText);
      const config: SchedulingConfig = { nurse1, nurse2, nurseC };
      const result = generateSchedule(patients, config);
      setSchedule(result);
    } catch (err: any) {
      setError(err.message || 'Có lỗi xảy ra khi xử lý dữ liệu.');
    }
  };

  const copyMarkdown = () => {
    if (schedule.length === 0) return;
    const header = '| STT | Tên bệnh nhân | Lần phun | Giờ thực hiện | Giờ kết thúc | Điều dưỡng | Mã máy | Ghi chú |\n|---|---|---|---|---|---|---|---|';
    const rows = schedule.map(s => 
      `| ${s.stt} | ${s.patientName} | Lần ${s.doseNumber} | ${s.startTime} | ${s.endTime} | ${s.nurseName} | ${s.machineId} | ${s.notes} |`
    ).join('\n');
    const table = `${header}\n${rows}`;
    navigator.clipboard.writeText(table);
    alert('Đã sao chép bảng Markdown vào bộ nhớ tạm!');
  };

  return (
    <div className="max-w-6xl mx-auto p-4 md:p-8">
      <header className="mb-8 text-center">
        <h1 className="text-3xl font-extrabold text-blue-900 mb-2">Hệ Thống Lập Lịch Phun Khí Dung 2026</h1>
        <p className="text-slate-500 uppercase tracking-widest text-sm">Chuẩn hóa quy trình & Tối ưu nguồn lực</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Input Section */}
        <div className="lg:col-span-1 space-y-6 bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Cấu hình nhân sự</label>
            <div className="space-y-3">
              <input 
                type="text" 
                placeholder="Tên Điều dưỡng trực 1"
                className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                value={nurse1}
                onChange={e => setNurse1(e.target.value)}
              />
              <input 
                type="text" 
                placeholder="Tên Điều dưỡng trực 2"
                className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                value={nurse2}
                onChange={e => setNurse2(e.target.value)}
              />
              <input 
                type="text" 
                placeholder="Tên Điều dưỡng C"
                className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                value={nurseC}
                onChange={e => setNurseC(e.target.value)}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Danh sách bệnh nhân</label>
            <p className="text-xs text-slate-400 mb-2 italic">Định dạng: Tên - Giờ lần 1 - Lần/ngày</p>
            <textarea 
              rows={10}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all font-mono text-sm"
              value={patientText}
              onChange={e => setPatientText(e.target.value)}
            />
          </div>

          <button 
            onClick={handleGenerate}
            className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl shadow-lg shadow-blue-200 transition-all transform active:scale-95"
          >
            Lập lịch ngay
          </button>

          {error && (
            <div className="p-3 bg-red-50 border border-red-200 text-red-600 text-sm rounded-lg">
              {error}
            </div>
          )}
        </div>

        {/* Output Section */}
        <div className="lg:col-span-2 space-y-4">
          <div className="flex justify-between items-center bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
            <h2 className="text-lg font-bold text-slate-800">Kết quả phân công</h2>
            {schedule.length > 0 && (
              <button 
                onClick={copyMarkdown}
                className="text-sm bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2 rounded-lg font-medium transition-colors"
              >
                Sao chép Markdown
              </button>
            )}
          </div>

          {schedule.length > 0 ? (
            <div className="overflow-x-auto bg-white rounded-2xl shadow-sm border border-slate-200">
              <table className="w-full text-left text-sm border-collapse">
                <thead>
                  <tr className="bg-slate-50 text-slate-600 font-semibold border-b border-slate-200">
                    <th className="px-4 py-3 text-center">STT</th>
                    <th className="px-4 py-3">Bệnh nhân</th>
                    <th className="px-4 py-3 text-center">Lần</th>
                    <th className="px-4 py-3">Bắt đầu</th>
                    <th className="px-4 py-3">Kết thúc</th>
                    <th className="px-4 py-3">Điều dưỡng</th>
                    <th className="px-4 py-3">Máy</th>
                    <th className="px-4 py-3">Ghi chú</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {schedule.map((row) => (
                    <tr key={`${row.patientName}-${row.doseNumber}`} className="hover:bg-blue-50/30 transition-colors">
                      <td className="px-4 py-3 text-center font-medium text-slate-400">{row.stt}</td>
                      <td className="px-4 py-3 font-semibold text-slate-900">{row.patientName}</td>
                      <td className="px-4 py-3 text-center">
                        <span className="bg-blue-100 text-blue-700 px-2 py-0.5 rounded text-xs font-bold">Lần {row.doseNumber}</span>
                      </td>
                      <td className="px-4 py-3 font-mono text-blue-600">{row.startTime}</td>
                      <td className="px-4 py-3 font-mono text-slate-500">{row.endTime}</td>
                      <td className="px-4 py-3 text-slate-700">{row.nurseName}</td>
                      <td className="px-4 py-3 font-mono font-bold text-slate-800">{row.machineId}</td>
                      <td className="px-4 py-3">
                        {row.isOffHours ? (
                          <span className="text-orange-600 bg-orange-50 px-2 py-0.5 rounded text-xs border border-orange-100 uppercase font-bold">Ngoài giờ</span>
                        ) : (
                          <span className="text-slate-400 text-xs italic">Hành chính</span>
                        )}
                        {row.notes && row.notes !== "Ngoài giờ" && (
                          <span className="ml-2 text-red-500 font-bold">{row.notes}</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="h-64 flex flex-col items-center justify-center bg-slate-100/50 rounded-2xl border-2 border-dashed border-slate-200 text-slate-400">
              <svg className="w-12 h-12 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
              <p>Nhập danh sách và nhấn "Lập lịch ngay" để xem kết quả.</p>
            </div>
          )}
        </div>
      </div>

      <footer className="mt-12 pt-6 border-t border-slate-200 text-center text-slate-400 text-xs uppercase tracking-widest">
        Dữ liệu được xử lý theo quy định lập lịch KD 2026 • Bảo mật & Chính xác
      </footer>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

