          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
            <input type="text" className="px-3 py-2 border rounded-lg text-sm outline-none focus:ring-1 focus:ring-indigo-500" value={nurse1} onChange={e => setNurse1(e.target.value)} placeholder="Điều dưỡng trực A" />
            <input type="text" className="px-3 py-2 border rounded-lg text-sm outline-none focus:ring-1 focus:ring-indigo-500" value={nurse2} onChange={e => setNurse2(e.target.value)} placeholder="Điều dưỡng trực B" />
            <input type="text" className="px-3 py-2 border rounded-lg text-sm outline-none focus:ring-1 focus:ring-indigo-500" value={nurseC} onChange={e => setNurseC(e.target.value)} placeholder="Điều dưỡng hành chính" />
          </div>
          <textarea 
            rows={5}
            className="w-full px-3 py-2 border rounded-lg text-sm mb-4 font-mono outline-none focus:ring-1 focus:ring-indigo-500"
            value={patientText}
            onChange={e => setPatientText(e.target.value)}
            placeholder="Tên - Giờ y lệnh - Số lần (VD: Nguyễn Văn A - 08:30 - 3)"
          />
          <div className="flex gap-2">
            <button onClick={handleGenerate} className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-2.5 rounded-lg text-sm uppercase transition-colors">Tạo lịch trình</button>
            {schedule.length > 0 && (
              <button onClick={handleDownloadPDF} className="bg-slate-800 hover:bg-black text-white px-6 py-2.5 rounded-lg text-sm font-bold uppercase transition-colors">Tải File PDF</button>
            )}
          </div>
          {error && <div className="mt-2 text-red-500 text-xs font-medium">{error}</div>}
        </div>

        {/* Output Table */}
        {schedule.length > 0 && (
          <div ref={printRef} className="bg-white rounded-lg border border-slate-200 overflow-hidden w-full shadow-sm">

            {/* PDF Header Section */}
            <div id="print-header" className="p-6 hidden text-center border-b-2 border-slate-800">
              <p className="font-bold uppercase text-[10pt] mb-1">TRUNG TÂM Y TẾ KHU VỰC CHỢ LÁCH</p>
