                  <th className="px-2 py-3 text-center border-r border-slate-200 bg-indigo-50/50 font-bold">Bắt đầu</th>
                  <th className="px-2 py-3 text-center border-r border-slate-200 font-bold">Kết thúc</th>
                  <th className="px-3 py-3 border-r border-slate-200">Điều dưỡng</th>
                  <th className="px-2 py-3 text-center border-r border-slate-200">Máy</th>
                  <th className="px-3 py-3">Ghi chú</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {schedule.map((row) => (
