    return text
      .split('\n')
      .filter((line) => line.trim())
      .map((line) => {
        const parts = line.split('-').map((s) => s.trim());
        if (parts.length < 3) throw new Error(`Dòng không đúng định dạng: ${line}`);
        const [name, time, freq] = parts;
